// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts1, uint256 ts2, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        vm.assume(ts1 > 0); // ensure the very first call can succeed for a wide range of timestamps

        // first call at ts1
        vm.warp(ts1);
        vm.deal(actor, 11 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        ok1; // not part of the assertion

        uint256 recorded = c.pastBlockTime();

        // second call at an arbitrary fuzzed ts2 (may be <= ts1)
        vm.warp(ts2);
        vm.deal(actor, 11 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // General rule: whenever a fallback call succeeds, pastBlockTime must strictly increase.
        // The reference always satisfies this; the mutant lets a same-timestamp call succeed
        // without increasing pastBlockTime.
        assertTrue(!ok2 || c.pastBlockTime() > recorded);
    }
}
